$activeMembers=$pdo->query("SELECT id FROM members WHERE membership_status IN ('Active','Suspended')")->fetchAll(PDO::FETCH_COLUMN);
foreach($activeMembers as $id){ sync_member_contributions((int)$id); }
$activeLoanIds=$pdo->query("SELECT id FROM loans WHERE status IN ('active','overdue','defaulted','fully_repaid')")->fetchAll(PDO::FETCH_COLUMN);
foreach($activeLoanIds as $id){ $pdo->beginTransaction();refresh_loan((int)$id);$pdo->commit(); }

require __DIR__.'/_header.php';

if($page==='dashboard'):
    $stats=$pdo->query("SELECT (SELECT COUNT(*) FROM members WHERE membership_status='Active') members,
      (SELECT COUNT(*) FROM members WHERE membership_status='Pending') pending_members,
      (SELECT COALESCE(SUM(amount),0) FROM financial_payments WHERE status='posted' AND payment_type='contribution') contributions,
      (SELECT COALESCE(SUM(principal_amount),0) FROM loans WHERE disbursed_on IS NOT NULL) issued,
      (SELECT COALESCE(SUM(outstanding_principal+outstanding_interest+outstanding_fees),0) FROM loans WHERE status IN ('active','overdue','defaulted')) outstanding,
      (SELECT COUNT(*) FROM loans WHERE status='overdue') overdue_loans,
      (SELECT COUNT(*) FROM loan_applications WHERE status IN ('submitted','under_review')) pending_loans,
      (SELECT COUNT(*) FROM payment_claims WHERE status='pending') pending_claims")->fetch();
