?>
<div class="portal-grid cards"><section class="portal-card"><span class="stat-label">Active members</span><strong class="stat-value"><?= (int)$stats['members'] ?></strong><span class="stat-note"><?= (int)$stats['pending_members'] ?> awaiting approval</span></section><section class="portal-card"><span class="stat-label">Contributions collected</span><strong class="stat-value"><?= kes($stats['contributions']) ?></strong><span class="stat-note">Cumulative verified payments</span></section><section class="portal-card"><span class="stat-label">Loan portfolio</span><strong class="stat-value"><?= kes($stats['outstanding']) ?></strong><span class="stat-note"><?= kes($stats['issued']) ?> issued</span></section><section class="portal-card"><span class="stat-label">Attention required</span><strong class="stat-value"><?= (int)$stats['pending_loans']+(int)$stats['pending_claims'] ?></strong><span class="stat-note"><?= (int)$stats['overdue_loans'] ?> overdue loan(s)</span></section></div>
