<?php elseif($page==='members'):
    $status=trim((string)($_GET['status']??''));$search=trim((string)($_GET['q']??''));$sort=(string)($_GET['sort']??'name');$memberPage=max(1,(int)($_GET['p']??1));$perPage=25;
    $where=[];$params=[];
    if($status==='Rejected'){$where[]="u.account_status='rejected'";}elseif($status==='Pending'){$where[]="m.membership_status='Pending' AND u.account_status='pending'";}elseif($status!==''){$where[]='m.membership_status=?';$params[]=$status;}
    if($search!==''){$where[]='(m.full_name LIKE ? OR m.membership_number LIKE ? OR u.phone LIKE ?)';$term='%'.$search.'%';array_push($params,$term,$term,$term);}
    $whereSql=$where?' WHERE '.implode(' AND ',$where):'';
    $count=$pdo->prepare('SELECT COUNT(*) FROM members m JOIN users u ON u.id=m.user_id'.$whereSql);$count->execute($params);$memberCount=(int)$count->fetchColumn();$totalPages=max(1,(int)ceil($memberCount/$perPage));$memberPage=min($memberPage,$totalPages);$offset=($memberPage-1)*$perPage;
    $sorts=['name'=>'m.full_name','joined'=>'m.date_joined DESC','contributions'=>'total_contributions DESC','loans'=>'outstanding_loan DESC'];$order=$sorts[$sort]??$sorts['name'];
    $sql="SELECT m.*,u.phone,u.role,u.account_status,CASE WHEN u.account_status='rejected' THEN 'Rejected' ELSE m.membership_status END AS membership_status,
